package com.huy.enterprise.product; import com.huy.enterprise.common.enums.RecordStatus; import jakarta.validation.constraints.*; import java.math.BigDecimal; import java.util.UUID; record ProductRequest(UUID categoryId,@NotBlank String productCode,@NotBlank String name,@NotBlank String unit,@PositiveOrZero BigDecimal referencePrice,String description,RecordStatus status){} record ProductResponse(UUID id,UUID categoryId,String categoryName,String productCode,String name,String unit,BigDecimal referencePrice,String description,RecordStatus status){static ProductResponse from(Product p){return new ProductResponse(p.getId(),p.getCategory()==null?null:p.getCategory().getId(),p.getCategory()==null?null:p.getCategory().getName(),p.getProductCode(),p.getName(),p.getUnit(),p.getReferencePrice(),p.getDescription(),p.getStatus());}} record CategoryRequest(@NotBlank String name,@NotBlank String code,String description,RecordStatus status){} record CategoryResponse(UUID id,String name,String code,String description,RecordStatus status){static CategoryResponse from(ProductCategory c){return new CategoryResponse(c.getId(),c.getName(),c.getCode(),c.getDescription(),c.getStatus());}}
